     1	/**
     2	 * Extracts the plain-text content of the first <li> starting with "Model is"
     3	 * from a sizeFit HTML string (SFCC c_sizeFit attribute).
     4	 */
     5	export function extractModelLine(html: string | undefined): string | undefined {
     6	  if (!html) return undefined;
     7	  const match = html.match(/<li>\s*(Model is[^<]*?)\s*<\/li>/i);
     8	  return match?.[1]?.trim() || undefined;
     9	}

