     3	type ProxyConfig = { host: string; path: string };
     4	type FullConfig = { app: Record<string, unknown>; ssrParameters?: { proxyConfigs?: ProxyConfig[] } };
     5	
     6	/**
     7	 * Rewrites an absolute SFCC static asset URL to go through the PWA Kit proxy,
     8	 * avoiding direct browser access to the Demandware host which is typically
     9	 * blocked by Cloudflare WAF outside of the Commerce Cloud network.
    10	 */
    11	export const proxyImageUrl = (url: string): string => {
    12	  try {
    13	    const { hostname, pathname, search } = new URL(url);
    14	    const { ssrParameters } = getConfig() as FullConfig;
    15	    const match = ssrParameters?.proxyConfigs?.find((c) => c.host === hostname);
    16	    if (match) return `/mobify/proxy/${match.path}${pathname}${search}`;
    17	  } catch (_) {
    18	    // relative or malformed URL — return as-is
    19	  }
    20	  return url;
    21	};
